  tick(): Promise<void> {
    if (!this.options.enabled) return Promise.resolve();
    if (this.running) return this.running;
    this.running = this.collect().catch(error => { this.archive.error = String(error); }).finally(() => { this.running = undefined; });
    return this.running;
  }
  private async collect() {
    const now = this.now();
    const data = await this.source.read(now);
    const current = new Map(data.processes.map(p => [p.identity, p]));
    const events: DiagnosticEvent[] = [];
    for (const [id, p] of current) if (!p.stale && !this.previous.has(id)) events.push({ kind: "started", identity: id, label: `${p.command} (${p.pid})`, observed_at: p.observed_at });
    // Empty fresh snapshots represent exits; unreadable snapshots are represented by a missing source marker below.
    const reliable = data.processesAvailable;
    if (reliable) {
      for (const [id, p] of this.previous) if (!current.has(id)) events.push({ kind: "exited", identity: id, label: `${p.command} (${p.pid})`, observed_at: now });
      this.previous = current;
    }
    const sample: DiagnosticSample = { schema_version: 1, record_type: "pipeline_diagnostics", session: this.archive.session, seq: this.seq++, observed_at: now,
      pipeline: data.pipeline, processes: data.processes, resources_available: data.processesAvailable, events };
    this.samples.push(sample);
    this.samples = this.samples.filter(s => s.observed_at >= now - this.options.historyMinutes * 60).slice(-(this.options.historyMinutes * 60 + 1));
    try { await this.archive.append(sample); } catch (error) { this.archive.error = String(error); }
    this.emit("sample", sample, this.status());
  }
  async stop() {
    if (this.timer) clearInterval(this.timer);
    if (this.running) await this.running;
    try { await this.archive.close(); } catch (error) { this.archive.error = String(error); }
  }
}
